        public boolean equals(Object o) {
            if (this == o)
                return true;
            if (o == null || getClass() != o.getClass())
                return false;

            SampleEntity that = (SampleEntity) o;

            if (rate != that.rate)
                return false;
            if (available != that.available)
                return false;
            if (!Objects.equals(id, that.id))
                return false;
            if (!Objects.equals(type, that.type))
